using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;

namespace LexisDesk {
    public static class ReviewTests {
        static readonly List<string> passed=new List<string>();
        static readonly DateTime Now=new DateTime(2026,10,16,23,59,0,DateTimeKind.Local);
        static void Check(bool value,string name){if(!value)throw new Exception("FAILED: "+name);passed.Add("PASS: "+name);}
        static bool Close(double a,double b){return Math.Abs(a-b)<1e-7*Math.Max(1,Math.Abs(b));}
        static Word First(Store s){return s.Queue(false,false,Now)[0];}
        static CardState Memory(double stability,double difficulty){return new CardState{Stability=stability,Difficulty=difficulty};}
        static CardState Mature(DateTime now,double stability=60,double difficulty=5){return new CardState{SchedulerVersion=1,Stage="review",Stability=stability,Difficulty=difficulty,LastReview=now.AddDays(-60).ToString("o"),Due=now.ToString("o"),IntervalDays=60,Level=6,Reviews=8};}
        public static int Run(string root){
            passed.Clear();var dir=Path.Combine(root,"review-tests",DateTime.Now.ToString("yyyyMMdd-HHmmss-fff"));Directory.CreateDirectory(dir);
            // Golden memory states independently generated by official ts-fsrs 5.4.2
            // next_state(), with default FSRS-6 parameters and short-term enabled.
            double[][] vectors={
                new double[]{0,0,0,1,.212,6.4133},new double[]{0,0,0,2,1.2931,5.11217071},
                new double[]{0,0,0,3,2.3065,2.11810397},new double[]{0,0,0,4,8.2956,1},
                new double[]{2.3065,2.11810397,0,3,2.3065,2.11121424},
                new double[]{60,5,60,1,3.08528927,8.34176237},new double[]{60,5,60,2,118.9691264,6.66599536},
                new double[]{60,5,60,3,158.05308679,4.99022837},new double[]{60,5,60,4,243.64362626,3.31446137},
                new double[]{60,8,90,3,124.60306465,7.98722837},new double[]{1,8,1,1,.30775829,9.32784197},
                new double[]{.001,10,0,1,.001,9.98522837},new double[]{100,9,365,3,209.35382424,8.98622837}
            };
            for(int i=0;i<vectors.Length;i++){var v=vectors[i];var card=Memory(v[0],v[1]);ReviewScheduler.UpdateMemory(card,(int)v[3],v[2]);Check(Close(card.Stability,v[4])&&Close(card.Difficulty,v[5]),"FSRS-6 official golden state "+(i+1));}
            Check(Close(ReviewScheduler.Recall(60,60),.9)&&ReviewScheduler.Recall(60,90)<.9,"model forgetting curve has 90% recall at stability and decreases with delay");
            Check(ReviewScheduler.Interval(.01)==1&&ReviewScheduler.Interval(10000)==365,"long-term intervals are bounded to 1..365 days");
            var hard=Memory(60,5);var good=Memory(60,5);ReviewScheduler.UpdateMemory(hard,2,60);ReviewScheduler.UpdateMemory(good,3,60);
            Check(hard.Stability<good.Stability&&hard.Difficulty>good.Difficulty,"effortful recall has a shorter model interval and higher difficulty than fluent recall");
            var overdue=Memory(60,5);ReviewScheduler.UpdateMemory(overdue,3,90);Check(overdue.Stability>good.Stability,"actual delay affects the next memory estimate");

            var s=new Store(Path.Combine(dir,"learning"));var word=First(s);
            var log=s.Grade(word,2,false,Now);var state=s.Data.Cards[word.Id];string due=state.Due,last=state.LastReview;double stability=state.Stability;
            Check(state.Stage=="learning"&&ReviewScheduler.Parse(due)==Now.AddMinutes(10),"initial fluent answer still schedules a 10-minute learning step across midnight");
            Check(!s.IsDue(word.Id,Now.AddMinutes(9))&&s.IsDue(word.Id,Now.AddMinutes(10)),"learning step becomes available at its exact deadline");
            var early=s.Grade(word,2,false,Now.AddSeconds(20));
            Check(early.Reinforcement&&!early.ScheduleUpdated&&state.Due==due&&state.LastReview==last&&state.Stability==stability,"early success cannot cancel the learning deadline or inflate memory");
            var repeated=s.Grade(word,0,false,Now.AddMinutes(11),true);
            Check(repeated.Reinforcement&&state.Due==due&&state.LastReview==last&&state.Lapses==0,"same-session repeat remains practice even after the deadline has passed");
            Check(s.ReviewedToday(Now.AddMinutes(11))==0,"practice is excluded from due-review statistics");
            log=s.Grade(word,2,false,Now.AddMinutes(12));
            Check(log.ScheduleUpdated&&!log.Reinforcement&&state.Stage=="review"&&ReviewScheduler.Parse(state.Due)==Now.AddMinutes(12).AddDays(state.IntervalDays),"delayed successful retrieval graduates with elapsed-time scheduling");
            Check(log.At==Now.AddMinutes(12).ToString("o")&&log.StageBefore=="learning"&&log.StageAfter=="review"&&log.ScheduledDue==state.Due&&Close(log.ElapsedDays,12.0/1440),"review logs preserve exact time, elapsed interval, stages and scheduled deadline");
            Check(s.ReviewedToday(Now.AddMinutes(12))==1,"real due recall counts as one reviewed word");
            var reload=new Store(s.DirectoryPath);Check(reload.Data.Cards[word.Id].Stability==state.Stability&&reload.Data.History.Last().ScheduledDue==state.Due,"memory state and detailed logs survive restart");
            var backup=Path.Combine(dir,"new-backup.json");JsonIO.Write(backup,s.Data);s.Data.Cards.Clear();s.Save();s.Restore(backup);
            Check(s.Data.Cards.ContainsKey(word.Id)&&s.Data.History.Last().ScheduleUpdated,"new-format backup restores memory and timed logs");

            s=new Store(Path.Combine(dir,"lapse"));word=First(s);s.Data.Cards[word.Id]=Mature(Now);state=s.Data.Cards[word.Id];
            s.Grade(word,0,false,Now);due=state.Due;stability=state.Stability;
            Check(state.Stage=="relearning"&&state.Stability<60&&state.Lapses==1&&ReviewScheduler.Parse(due)==Now.AddMinutes(10),"mature lapse lowers stability and enters short-term relearning");
            s.Grade(word,2,false,Now.AddSeconds(30),true);Check(state.Due==due&&state.Stability==stability&&state.Stage=="relearning","forgot-then-immediate-success regression keeps relearning due");
            s.Grade(word,1,false,Now.AddMinutes(10));Check(state.Stage=="relearning"&&ReviewScheduler.Parse(state.Due)==Now.AddMinutes(20),"effortful relearning repeats the short step instead of graduating");
            s.Grade(word,2,false,Now.AddMinutes(20));Check(state.Stage=="review"&&state.IntervalDays<60,"successful relearning does not restore the old 60-day level");

            s=new Store(Path.Combine(dir,"hard"));word=First(s);s.Data.Cards[word.Id]=Mature(Now);state=s.Data.Cards[word.Id];
            s.Grade(word,1,false,Now);Check(state.IntervalDays==119&&state.Difficulty>5,"mature effortful recall uses FSRS, without the former forced-next-day then level rebound");
            due=state.Due;last=state.LastReview;stability=state.Stability;s.Grade(word,2,false,Now.AddDays(1));
            Check(state.Due==due&&state.LastReview==last&&state.Stability==stability,"premature mature review cannot escalate the interval");
            s.Grade(word,0,true,Now.AddDays(1));Check(state.Due==due&&state.LastReview==last,"spelling error keeps meaning-recall scheduling independent");

            s=new Store(Path.Combine(dir,"legacy"));word=First(s);state=new CardState{Level=6,Reviews=7,Lapses=2,Due=Now.ToString("o")};s.Data.Cards[word.Id]=state;
            s.Data.Favorites.Add(word.Id);s.Data.History.Add(new AnswerLog{Day=Store.Day(Now.AddDays(-60)),Id=word.Id,Grade=2});s.Save();
            string original=File.ReadAllText(s.StatePath);reload=new Store(s.DirectoryPath);
            Check(reload.Data.Cards[word.Id].SchedulerVersion==0&&reload.Data.Cards[word.Id].Due==state.Due&&File.ReadAllText(s.StatePath)==original,"loading a legacy fixture neither invents timestamps nor rewrites due dates");
            reload.Grade(reload.Words[word.Id],2,false,Now);var adopted=reload.Data.Cards[word.Id];
            Check(adopted.SchedulerVersion==1&&adopted.Reviews==8&&adopted.Lapses==2&&reload.Data.Favorites.Contains(word.Id)&&adopted.ScheduleReason.Contains("近似"),"legacy due answer adopts an explicitly approximate memory seed and retains progress");
            Check(reload.Data.History.First().At==null&&reload.Data.History.Last().At!=null,"legacy logs remain date-only while new answers get exact timestamps");
            var oldBackup=Path.Combine(dir,"old-backup.json");JsonIO.Write(oldBackup,s.Data);reload.Restore(oldBackup);
            Check(reload.Data.Cards[word.Id].SchedulerVersion==0&&reload.Data.Cards[word.Id].Due==state.Due,"restoring an old-format backup retains the original schedule");
            reload.Data.Cards[word.Id].Due=Now.AddDays(5).ToString("o");reload.Grade(reload.Words[word.Id],2,false,Now);
            Check(reload.Data.Cards[word.Id].SchedulerVersion==0,"early legacy practice cannot silently migrate or reschedule a future card");

            s=new Store(Path.Combine(dir,"queue"));var other=s.Words.Values.First(w=>!s.Selected().WordIds.Contains(w.Id));
            s.Data.Cards[other.Id]=Mature(Now.AddMinutes(-5));word=First(s);s.Data.Cards[word.Id]=Mature(Now.AddMinutes(-1));
            Check(s.DueCount(Now)==2&&s.Queue(true,false,Now).First().Id==other.Id,"all-book review includes old books and sorts by actual deadline");
            s.SetExcluded(other.Id,true);Check(s.DueCount(Now)==1&&!s.Queue(true,false,Now).Any(w=>w.Id==other.Id),"global review honors never-review exclusions");
            int history=s.Data.History.Count;s.Grade(other,0,false,Now);Check(s.Data.History.Count==history,"stale answer cannot reactivate an excluded word");
            s.SetExcluded(other.Id,false);Check(s.DueCount(Now)==2,"restoring an exclusion preserves the due schedule");
            foreach(var item in s.Words.Values.Take(120))s.Data.Cards[item.Id]=Mature(Now.AddMinutes(-2));
            Check(s.Queue(true,false,Now).Count==100&&s.DueCount(Now)>100,"round cap does not hide the total backlog");
            s.Data.Cards[word.Id].Due=Now.ToUniversalTime().AddMinutes(10).ToString("o");
            Check(!s.IsDue(word.Id,Now.AddMinutes(9))&&s.IsDue(word.Id,Now.AddMinutes(10)),"UTC-encoded backup deadlines are compared at the correct instant");
            Check(Close(ReviewScheduler.Elapsed(Now,Now.ToUniversalTime()),0),"mixed UTC and local review timestamps represent the same instant");
            var future=new Store(Path.Combine(dir,"validation"));word=First(future);future.Data.Cards[word.Id]=Mature(Now);future.Data.Cards[word.Id].Stability=double.NaN;
            bool rejected=false;try{Store.Validate(future.Data);}catch(InvalidDataException){rejected=true;}Check(rejected,"invalid numerical memory state is rejected before saving");
            future.Data.Cards[word.Id]=Mature(Now);future.Data.Cards[word.Id].SchedulerVersion=99;rejected=false;try{Store.Validate(future.Data);}catch(InvalidDataException){rejected=true;}Check(rejected,"unknown future scheduler versions are rejected rather than overwritten");
            File.WriteAllLines(Path.Combine(root,"review-test-results.txt"),passed,new UTF8Encoding(false));return 0;
        }
        static bool Contains(DependencyObject root,string text){var t=root as TextBlock;if(t!=null&&t.Text.Contains(text))return true;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)if(Contains(VisualTreeHelper.GetChild(root,i),text))return true;return false;}
        public static void UI(string root,Application app){
            passed.Clear();var dir=Path.Combine(root,"review-ui-tests",DateTime.Now.ToString("yyyyMMdd-HHmmss-fff"));Directory.CreateDirectory(dir);
            var s=new Store(Path.Combine(dir,"state"));var word=First(s);s.Data.CustomBooks.Add(new Book{Id="test",Name="单词重学测试",WordIds=new List<string>{word.Id}});s.Data.SelectedBook="test";
            var window=new MainWindow(s){ThrowOnError=true,ShowInTaskbar=false,Left=-16000,Top=-16000,WindowStartupLocation=WindowStartupLocation.Manual};window.Show();
            try {
                window.StartSession(false,false);window.Reveal();window.Answer(0);string due=s.Data.Cards[word.Id].Due;
                window.RenderTo(Path.Combine(dir,"01-reinforcement.png"));Check(Contains((DependencyObject)window.Content,"本轮重现只作巩固")&&Contains((DependencyObject)window.Content,"初学巩固"),"study UI explains short-term practice and shows next due");
                window.Reveal();window.Answer(2);Check(s.Data.Cards[word.Id].Due==due&&s.Data.History.Last().Reinforcement,"actual UI repeat success preserves original 10-minute deadline");
                window.Navigate("today");window.UpdateLayout();Check(Contains((DependencyObject)window.Content,"全部已学词书")&&Contains((DependencyObject)window.Content,"下次到期"),"home shows global review scope and upcoming deadline");
                s.Data.Cards[word.Id].Due=DateTime.Now.AddSeconds(-1).ToString("o");
                s.Data.CustomBooks.Add(new Book{Id="another-book",Name="其他词书",WordIds=new List<string>{s.Words.Values.First(w=>w.Id!=word.Id).Id}});s.Data.SelectedBook="another-book";
                window.StartSession(true,false);window.Reveal();window.Answer(2);Check(!s.Selected().WordIds.Contains(word.Id)&&s.Data.Cards[word.Id].Stage=="review"&&s.Data.History.Last().ScheduleUpdated,"actual UI reviews due words from a different selected book");
                s.Data.SelectedBook="cet4";
                window.Navigate("stats");window.RenderTo(Path.Combine(dir,"02-stats.png"));Check(Contains((DependencyObject)window.Content,"较长复习间隔")&&!Contains((DependencyObject)window.Content,"记忆稳定"),"statistics avoids claiming scientifically measured stability");
                window.Navigate("settings");window.RenderTo(Path.Combine(dir,"03-settings.png"));Check(Contains((DependencyObject)window.Content,"FSRS-6")&&Contains((DependencyObject)window.Content,"尚未按你的个人数据训练"),"settings discloses model defaults and limits");
                window.Navigate("today");window.RenderTo(Path.Combine(dir,"04-today.png"));
            } finally {window.Close();}
            File.WriteAllLines(Path.Combine(root,"review-ui-test-results.txt"),passed,new UTF8Encoding(false));
        }
    }
}
